<script setup>
import { computed, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { jointStore as store, clone, displayTime, localDate } from '../../data/equipmentInspectionMock.js'
import TaskResults from './TaskResults.vue'
const route=useRoute(),tab=ref('tasks'),page=ref(1),detailId=ref('')
const filters=ref({text:'',objectId:'',result:'',period:'',periodType:'日'}),applied=ref(clone(filters.value))
const records=computed(()=>store.records())
const objectOptions=computed(()=>{const objects=new Map();records.value.forEach(row=>objects.set(row.object.id,row.object));return [...objects.values()]})
const filtered=computed(()=>records.value.filter(row=>(!applied.value.text || `${row.taskCode}${row.taskName}`.includes(applied.value.text)) && (!applied.value.objectId || row.object.id===applied.value.objectId) && (!applied.value.result || row.decision===applied.value.result) && (!applied.value.period || localDate(row.checkedAt).startsWith(applied.value.period))))
const completedTasks=computed(()=>store.state.tasks.filter(task=>task.status==='已完成' && filtered.value.some(row=>row.taskId===task.id)).slice().sort((a,b)=>b.submittedAt.localeCompare(a.submittedAt)))
const ledger=computed(()=>{const grouped=new Map();for(const row of filtered.value){const id=`${row.taskId}|${row.point.id}|${row.object.id}`;if(!grouped.has(id))grouped.set(id,{id,taskId:row.taskId,taskCode:row.taskCode,object:row.object,point:row.point,date:row.date,slotStart:row.slotStart,plannedAt:row.plannedAt,checkedAt:row.checkedAt,checkedByName:row.checkedByName,rows:[]});grouped.get(id).rows.push(row)}return [...grouped.values()].sort((a,b)=>b.checkedAt.localeCompare(a.checkedAt)||a.object.code.localeCompare(b.object.code))})
const detail=computed(()=>store.state.tasks.find(task=>task.id===detailId.value && task.status==='已完成'))
function query(){applied.value=clone(filters.value);applied.value.text=applied.value.text.trim();page.value=1}
function reset(){filters.value={text:'',objectId:'',result:'',period:'',periodType:'日'};query()}
watch(tab,()=>page.value=1)
watch(()=>[route.query.task,route.query.object],([taskId,objectId])=>{if(objectId){filters.value.objectId=String(objectId);tab.value='ledger';query()}if(taskId){filters.value.text=store.byId(store.state.tasks,String(taskId))?.code || String(taskId);query();detailId.value=String(taskId)}},{immediate:true})
const tone=value=>value==='异常'?'danger':value==='正常'?'success':'info'
</script>
<template>
  <main class="inspection-page"><header class="heading"><div><div class="eyebrow">巡检管理 / 原始结果追溯</div><h1>巡检记录</h1><p class="subtitle">按任务追溯本次检查，或按设备与实际检查日期查看多时段电子台账。</p></div><router-link to="/inspection/tasks"><el-button type="primary" plain>前往巡检任务</el-button></router-link></header><p class="demo-note">本地 Mock 演示 · 记录直接来自已提交任务结果，没有第二套手工录入台账。内置历史样本位于 2026-10-28；没有参考条件的读数保留“未自动判定”。</p><el-alert v-if="store.notice.persistence" :title="store.notice.persistence" type="warning" :closable="false" />
    <section class="panel"><el-tabs v-model="tab"><el-tab-pane label="按任务查看" name="tasks" /><el-tab-pane label="设备日 / 月电子台账" name="ledger" /></el-tabs><el-form class="filters" @submit.prevent="query"><el-input v-model="filters.text" aria-label="记录任务查询" placeholder="任务编号 / 计划名称" clearable /><el-select v-model="filters.objectId" aria-label="记录实际对象" clearable filterable placeholder="全部设备 / 空间"><el-option v-for="row in objectOptions" :key="row.id" :value="row.id" :label="`${row.code} · ${row.name}`" /><el-option v-for="row in store.state.assets.filter(asset=>!objectOptions.some(object=>object.id===asset.id))" :key="row.id" :value="row.id" :label="`${row.code} · ${row.name}（暂无记录）`" /></el-select><el-select v-model="filters.result" aria-label="记录判定筛选" clearable placeholder="全部判定结果"><el-option v-for="value in ['正常','异常','未自动判定']" :key="value" :value="value" /></el-select><el-radio-group v-model="filters.periodType" @change="filters.period=''"><el-radio-button value="日">日</el-radio-button><el-radio-button value="月">月</el-radio-button></el-radio-group><el-date-picker v-model="filters.period" :key="filters.periodType" :type="filters.periodType==='月'?'month':'date'" :value-format="filters.periodType==='月'?'YYYY-MM':'YYYY-MM-DD'" :placeholder="`实际检查${filters.periodType}期`" aria-label="记录实际检查日期" style="width:170px" /><el-button type="primary" native-type="submit">查询</el-button><el-button @click="reset">重置</el-button></el-form>
      <p class="caption">{{ filtered.length }} 条原始结果 / {{ completedTasks.length }} 次任务 · 编号与对象 ID 分开归属，实际检查时间不回填为计划时间</p>
      <el-table v-if="tab==='tasks'" :data="completedTasks.slice((page-1)*10,page*10)" stripe empty-text="暂无已提交结果；请完成任务，或重置日期 / 对象筛选"><el-table-column label="任务 / 来源计划" min-width="240"><template #default="{row}"><el-button link type="primary" class="title-button" @click="detailId=row.id">{{ row.planName }}</el-button><p class="muted">{{ row.code }}{{ row.seeded?' · 内置样本':'' }}</p></template></el-table-column><el-table-column label="计划日期 / 时段" min-width="155"><template #default="{row}">{{ row.date }}<div class="muted">{{ row.slot.start }}—{{ row.slot.end }}</div></template></el-table-column><el-table-column label="实际提交 / 检查人" min-width="190"><template #default="{row}">{{ displayTime(row.submittedAt) }}<div class="muted">{{ row.personName }}</div></template></el-table-column><el-table-column label="检查结果 / 时间状态" min-width="170"><template #default="{row}"><el-tag :type="store.taskSummary(row)==='存在异常'?'danger':'info'">{{ store.taskSummary(row) }}</el-tag><div class="muted">{{ store.timeStatus(row) }}</div></template></el-table-column><el-table-column label="原始记录" width="130" fixed="right"><template #default="{row}"><el-button link type="primary" @click="detailId=row.id">查看本次结果</el-button></template></el-table-column></el-table>
      <el-table v-else :data="ledger.slice((page-1)*10,page*10)" stripe empty-text="当前设备 / 日期没有已提交记录"><el-table-column label="实际对象" min-width="180"><template #default="{row}"><strong>{{ row.object.name }}</strong><div class="muted">{{ row.object.code }} · {{ row.object.type }}</div><p class="muted">检查位置：{{ row.point.name }}</p></template></el-table-column><el-table-column label="计划时段 / 实际检查" min-width="190"><template #default="{row}">{{ row.date }} {{ row.slotStart }}<div class="muted">{{ displayTime(row.checkedAt) }}</div><div class="muted">{{ row.checkedByName }}</div></template></el-table-column><el-table-column label="本时段原始读数 / 结论" min-width="310"><template #default="{row}"><div v-for="result in row.rows" :key="result.id" class="ledger-line"><span><small class="muted">{{ result.groupName }} · </small>{{ result.item.name }}：<strong>{{ result.item.type==='照片'?`${result.photos.length}张本地照片`:result.value }}</strong> {{ result.unit }}</span><el-tag :type="tone(result.decision)" size="small">{{ result.decision }}</el-tag><p v-if="result.note" class="ledger-note">{{ result.note }}</p></div></template></el-table-column><el-table-column label="来源任务" min-width="170"><template #default="{row}"><el-button link type="primary" class="title-button" @click="detailId=row.taskId">{{ row.taskCode }}</el-button><p class="muted">只读，同一数据来源</p></template></el-table-column></el-table>
      <el-pagination v-model:current-page="page" :total="tab==='tasks'?completedTasks.length:ledger.length" :page-size="10" layout="total, prev, pager, next" class="pagination" />
    </section>
    <el-drawer :model-value="Boolean(detail)" title="已提交巡检原始记录（只读）" size="min(900px,94vw)" append-to-body @close="detailId=''"><template v-if="detail"><h2>{{ detail.planName }}</h2><dl class="detail-list"><dt>来源任务</dt><dd>{{ detail.code }} · 计划 V{{ detail.planVersion }}</dd><dt>规则快照</dt><dd>{{ detail.rule.name }} V{{ detail.rule.version }}</dd><dt>计划时段</dt><dd>{{ displayTime(detail.scheduledStart) }} — {{ displayTime(detail.deadline) }}</dd><dt>实际提交</dt><dd>{{ displayTime(detail.submittedAt) }}</dd><dt>检查结果</dt><dd>{{ store.taskSummary(detail) }} · {{ store.timeStatus(detail) }}</dd></dl><TaskResults :task="detail" /><router-link :to="{path:'/inspection/tasks',query:{task:detail.id}}"><el-button type="primary" plain>打开来源任务</el-button></router-link></template></el-drawer>
  </main>
</template>
<style scoped src="./inspection.css"></style>
<style scoped>
.ledger-line{padding:8px 0;border-bottom:1px solid var(--ez-border-light);display:flex;align-items:center;gap:8px;flex-wrap:wrap}.ledger-line:last-child{border:0}.ledger-note{width:100%;font-size:12px;color:var(--ez-warning-text);line-height:1.7;overflow-wrap:anywhere}
</style>
